    async def update(
        self,
        id: str,
        *,
        first_name: typing.Optional[str] = OMIT,
        last_name: typing.Optional[str] = OMIT,
        properties: typing.Optional[typing.Dict[str, typing.Optional[UpdateContactRequestPropertiesValue]]] = OMIT,
        status: typing.Optional[UpdateContactRequestStatus] = OMIT,
        topics: typing.Optional[typing.Sequence[UpdateContactRequestTopicsItem]] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> Contact:
        """
        Changes the fields given; `properties` are merged (`null` removes one).

        Parameters
        ----------
        id : str
            The contact's id, or its address (URL-encoded).

        first_name : typing.Optional[str]

        last_name : typing.Optional[str]

        properties : typing.Optional[typing.Dict[str, typing.Optional[UpdateContactRequestPropertiesValue]]]
            Custom properties by key (define them first, see contact properties). Merged into the contact's existing properties; `null` removes one.

        status : typing.Optional[UpdateContactRequestStatus]
            Sets the contact's consent. Omitted, a new contact is `subscribed` and an existing one keeps its status.

        topics : typing.Optional[typing.Sequence[UpdateContactRequestTopicsItem]]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        Contact
            The contact.

        Examples
        --------
        import asyncio

        from coss import AsyncCoss

        client = AsyncCoss(
            "2026-10-10",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.email.contacts.update(
                id="contact_01k7c8m4q2f3e9v6t5r1n0p8yz",
                last_name="Byron",
                properties={},
            )


        asyncio.run(main())
        """
        _response = await self._raw_client.update(
            id,
            first_name=first_name,
            last_name=last_name,
            properties=properties,
            status=status,
            topics=topics,
            request_options=request_options,
        )
        return _response.data

